import { Accessor, For, JSX, Show } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface ForWithSeparatorProps<T extends readonly unknown[], U extends JSX.Element> {
	each: T | undefined | null | false;
	fallback?: JSX.Element;
	separator: JSX.Element;
	children: (item: T[number], index: Accessor<number>) => U;
}

function ForWithSeparatorComponent<T extends readonly unknown[], U extends JSX.Element>(
	props: ForWithSeparatorProps<T, U>,
) {
	return (
		<For
			fallback={props.fallback}
			each={props.each}
		>
			{(item: T | undefined | null | false, index: Accessor<number>) => (
				<>
					<Show when={index() != 0}>{props.separator}</Show>
					{props.children(item, index)}
				</>
			)}
		</For>
	);
}

export const ForWithSeparator = ComponentRegistry.register("ForWithSeparator", ForWithSeparatorComponent);
